        if task["id"] in completed or task["id"] in active_ids:
            continue
        if not set(task["dependencies"]) <= completed:
            continue

        task_scopes = [canonical(scope) for scope in task["writes"]]
        if any(_overlap(scope, occupied) for scope in task_scopes
